"use client"

/**
 * Clean-room company table. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, or assets were copied.
 * crm-table is the fixed contact layout. This one is the company book.
 */

import * as React from "react"
import { ChevronDown, ChevronUp, Download } from "lucide-react"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { downloadCsv, toCsv } from "@/lib/csv"
import {
  crmInitials,
  paginate,
  sortCompanies,
  type CrmCompany,
  type CrmCsvLabels,
  type CrmSort,
  type CrmSortKey,
  type CrmStatusTone,
} from "@/lib/crm-companies"
import { Sparkline } from "@/components/ui/sparkline"

export type CrmCompaniesTableLabels = {
  caption?: string
  name?: string
  status?: string
  owner?: string
  pipeline?: string
  score?: string
  activity?: string
  selectAll?: string
  selectRow?: (company: CrmCompany) => string
  openRow?: (company: CrmCompany) => string
  empty?: string
  loading?: string
  selected?: (count: number) => string
  range?: (start: number, end: number, total: number) => string
  previous?: string
  next?: string
  page?: (page: number, pages: number) => string
  export?: string
  sort?: (label: string) => string
}

export type CrmCompaniesTableProps = {
  rows: readonly CrmCompany[]
  sort?: CrmSort
  defaultSort?: CrmSort
  onSortChange?: (sort: CrmSort) => void
  selectedIds?: string[]
  defaultSelectedIds?: string[]
  onSelectedIdsChange?: (ids: string[]) => void
  page?: number
  defaultPage?: number
  pageSize?: number
  onPageChange?: (page: number) => void
  onRowOpen?: (company: CrmCompany) => void
  onExport?: (rows: readonly CrmCompany[]) => void
  formatValue?: (value: number) => string
  csvLabels?: Partial<CrmCsvLabels>
  exportFilename?: string
  loading?: boolean
  labels?: CrmCompaniesTableLabels
  className?: string
}

const TONE_VARIANT: Record<CrmStatusTone, "default" | "secondary" | "outline" | "destructive"> = {
  emphasis: "default",
  neutral: "secondary",
  muted: "outline",
  danger: "destructive",
}

const COLUMNS: { key: CrmSortKey; label: keyof CrmCompaniesTableLabels }[] = [
  { key: "name", label: "name" },
  { key: "status", label: "status" },
  { key: "owner", label: "owner" },
  { key: "pipeline", label: "pipeline" },
  { key: "score", label: "score" },
  { key: "activity", label: "activity" },
]

function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (next: T) => void) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value ?? internal
  const set = React.useCallback(
    (next: T) => {
      if (value === undefined) setInternal(next)
      onChange?.(next)
    },
    [onChange, value],
  )
  return [current, set] as const
}

export function CrmCompaniesTable({
  rows,
  sort: sortProp,
  defaultSort = { key: "name", direction: "asc" },
  onSortChange,
  selectedIds: selectedProp,
  defaultSelectedIds = [],
  onSelectedIdsChange,
  page: pageProp,
  defaultPage = 0,
  pageSize = 8,
  onPageChange,
  onRowOpen,
  onExport,
  formatValue = (value) => new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(value),
  csvLabels,
  exportFilename = "companies.csv",
  loading = false,
  labels,
  className,
}: CrmCompaniesTableProps) {
  const copy = {
    caption: labels?.caption ?? "Companies",
    name: labels?.name ?? "Name",
    status: labels?.status ?? "Status",
    owner: labels?.owner ?? "Owner",
    pipeline: labels?.pipeline ?? "Pipeline",
    score: labels?.score ?? "Score",
    activity: labels?.activity ?? "Activity",
    selectAll: labels?.selectAll ?? "Select all on this page",
    empty: labels?.empty ?? "No companies",
    loading: labels?.loading ?? "Loading companies",
    previous: labels?.previous ?? "Previous page",
    next: labels?.next ?? "Next page",
    export: labels?.export ?? "Export CSV",
  }
  const columnLabel: Record<CrmSortKey, string> = {
    name: copy.name,
    status: copy.status,
    owner: copy.owner,
    pipeline: copy.pipeline,
    score: copy.score,
    activity: copy.activity,
  }
  const [sort, setSort] = useControllable(sortProp, defaultSort, onSortChange)
  const [selectedIds, setSelectedIds] = useControllable(selectedProp, [...defaultSelectedIds], onSelectedIdsChange)
  const [page, setPage] = useControllable(pageProp, defaultPage, onPageChange)
  const sorted = React.useMemo(() => sortCompanies(rows, sort), [rows, sort])
  const paged = paginate(sorted, page, pageSize)
  const pageIds = paged.rows.map((company) => company.id)
  const selectedOnPage = pageIds.filter((id) => selectedIds.includes(id))
  const allSelected = pageIds.length > 0 && selectedOnPage.length === pageIds.length
  const someSelected = selectedOnPage.length > 0 && !allSelected

  function toggleSort(key: CrmSortKey) {
    setSort(sort.key === key ? { key, direction: sort.direction === "asc" ? "desc" : "asc" } : { key, direction: "asc" })
  }

  function togglePage(checked: boolean) {
    if (checked) setSelectedIds([...new Set([...selectedIds, ...pageIds])])
    else setSelectedIds(selectedIds.filter((id) => !pageIds.includes(id)))
  }

  function toggleRow(id: string, checked: boolean) {
    setSelectedIds(checked ? [...selectedIds, id] : selectedIds.filter((item) => item !== id))
  }

  function exportRows() {
    const chosen = selectedIds.length > 0 ? sorted.filter((company) => selectedIds.includes(company.id)) : sorted
    if (onExport) onExport(chosen)
    else downloadCsv(exportFilename, companiesToCsv(chosen, csvLabels, formatValue))
  }

  const range =
    paged.total === 0
      ? labels?.range?.(0, 0, 0) ?? "0 companies"
      : labels?.range?.(paged.start + 1, paged.end, paged.total) ?? `${paged.start + 1}–${paged.end} of ${paged.total}`

  return (
    <div data-slot="crm-companies-table" className={cn("flex min-w-0 flex-col gap-3", className)}>
      <div className="max-h-[28rem] min-w-0 contain-paint overflow-auto rounded-xl border border-border">
        <table data-slot="table" className="w-full min-w-[44rem] caption-bottom text-sm" aria-busy={loading || undefined}>
          <caption className="sr-only">{copy.caption}</caption>
          <TableHeader className="sticky top-0 z-20 bg-background shadow-sm">
            <TableRow>
              <TableHead className="sticky start-0 z-30 w-10 bg-background">
                <Checkbox
                  checked={allSelected ? true : someSelected ? "indeterminate" : false}
                  onCheckedChange={(checked) => togglePage(checked === true)}
                  disabled={loading || pageIds.length === 0}
                  aria-label={copy.selectAll}
                />
              </TableHead>
              {COLUMNS.map((column) => {
                const active = sort.key === column.key
                const label = columnLabel[column.key]
                return (
                  <TableHead
                    key={column.key}
                    aria-sort={active ? (sort.direction === "asc" ? "ascending" : "descending") : "none"}
                    className={cn("sticky top-0 bg-background", column.key === "name" && "start-10 z-30")}
                  >
                    <button
                      type="button"
                      className="inline-flex items-center gap-1 rounded-md text-start focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                      onClick={() => toggleSort(column.key)}
                    >
                      {label}
                      <span className="sr-only">{labels?.sort?.(label) ?? `, sort by ${label}`}</span>
                      {active ? (
                        sort.direction === "asc" ? (
                          <ChevronUp aria-hidden="true" />
                        ) : (
                          <ChevronDown aria-hidden="true" />
                        )
                      ) : null}
                    </button>
                  </TableHead>
                )
              })}
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={7} className="py-10 text-center text-muted-foreground">
                  {copy.loading}
                </TableCell>
              </TableRow>
            ) : paged.rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} className="py-10 text-center text-muted-foreground">
                  {copy.empty}
                </TableCell>
              </TableRow>
            ) : (
              paged.rows.map((company) => {
                const selected = selectedIds.includes(company.id)
                return (
                  <TableRow key={company.id} data-state={selected ? "selected" : undefined}>
                    <TableCell className="sticky start-0 z-10 bg-background">
                      <Checkbox
                        checked={selected}
                        onCheckedChange={(checked) => toggleRow(company.id, checked === true)}
                        aria-label={labels?.selectRow?.(company) ?? `Select ${company.name}`}
                      />
                    </TableCell>
                    <TableCell className="sticky start-10 z-10 max-w-56 bg-background">
                      <button
                        type="button"
                        className="flex min-w-0 items-center gap-2 rounded-md text-start focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                        onClick={() => onRowOpen?.(company)}
                      >
                        <Avatar size="sm">
                          {company.logoUrl ? <AvatarImage src={company.logoUrl} alt="" /> : null}
                          <AvatarFallback>{crmInitials(company.name)}</AvatarFallback>
                        </Avatar>
                        <span className="min-w-0 truncate font-medium">{company.name}</span>
                        <span className="sr-only">{labels?.openRow?.(company) ?? `, open ${company.name}`}</span>
                      </button>
                    </TableCell>
                    <TableCell>
                      <Badge variant={TONE_VARIANT[company.statusTone ?? "neutral"]}>{company.statusLabel}</Badge>
                    </TableCell>
                    <TableCell className="max-w-40 truncate">{company.owner}</TableCell>
                    <TableCell className="text-end tabular-nums">{formatValue(company.pipelineValue)}</TableCell>
                    <TableCell>
                      <div
                        className="flex items-center gap-2"
                        role="meter"
                        aria-valuemin={0}
                        aria-valuemax={100}
                        aria-valuenow={Math.max(0, Math.min(100, company.score))}
                        aria-label={copy.score}
                      >
                        <span className="w-8 shrink-0 text-end tabular-nums">{company.score}</span>
                        <span className="relative h-1.5 w-16 overflow-hidden rounded-full bg-muted" aria-hidden="true">
                          <span
                            className="absolute inset-y-0 start-0 bg-primary"
                            style={{ width: `${Math.max(0, Math.min(100, company.score))}%` }}
                          />
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="w-36">
                      {company.activity.length > 1 ? (
                        <Sparkline
                          data={[...company.activity]}
                          label={company.activityLabel}
                          interactive={false}
                          width={112}
                          height={28}
                          className="w-28"
                          classNames={{ root: "gap-0", caption: "sr-only" }}
                        />
                      ) : (
                        <span className="text-muted-foreground">{company.activityLabel}</span>
                      )}
                    </TableCell>
                  </TableRow>
                )
              })
            )}
          </TableBody>
        </table>
      </div>
      <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
        <p className="min-w-0 flex-1" aria-live="polite">
          {selectedIds.length > 0 ? (
            <span className="me-3 text-foreground">{labels?.selected?.(selectedIds.length) ?? `${selectedIds.length} selected`}</span>
          ) : null}
          <span>{range}</span>
          <span className="ms-3">{labels?.page?.(paged.page + 1, paged.pages) ?? `${paged.page + 1} / ${paged.pages}`}</span>
        </p>
        <Button type="button" variant="outline" size="sm" onClick={() => setPage(paged.page - 1)} disabled={paged.page === 0 || loading}>
          {copy.previous}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setPage(paged.page + 1)}
          disabled={paged.page >= paged.pages - 1 || loading}
        >
          {copy.next}
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={exportRows} disabled={loading || sorted.length === 0}>
          <Download data-icon="inline-start" aria-hidden="true" />
          {copy.export}
        </Button>
      </div>
    </div>
  )
}

const DEFAULT_CSV_LABELS: CrmCsvLabels = {
  name: "Name",
  status: "Status",
  owner: "Owner",
  pipeline: "Pipeline",
  score: "Score",
  activity: "Activity",
}

export function companiesToCsv(
  rows: readonly CrmCompany[],
  labels: Partial<CrmCsvLabels> = {},
  formatValue: (value: number) => string = (value) => String(value),
) {
  const headers = { ...DEFAULT_CSV_LABELS, ...labels }
  const columns = [
    { key: "name", header: headers.name },
    { key: "status", header: headers.status },
    { key: "owner", header: headers.owner },
    { key: "pipeline", header: headers.pipeline },
    { key: "score", header: headers.score },
    { key: "activity", header: headers.activity },
  ]
  const records = rows.map((company) => ({
    name: company.name,
    status: company.statusLabel,
    owner: company.owner,
    pipeline: formatValue(company.pipelineValue),
    score: company.score,
    activity: company.activityLabel,
  }))
  return toCsv(records, columns)
}

/**
 * Clean-room sales CRM model. Behavior is inspired by an unlicensed reference.
 * No source, class names, copy, sample rows, or assets were copied.
 */

export type CrmStatusTone = "neutral" | "emphasis" | "muted" | "danger"

export type CrmCompany = {
  id: string
  name: string
  logoUrl?: string
  status: string
  statusLabel: string
  statusTone?: CrmStatusTone
  owner: string
  ownerId?: string
  pipelineValue: number
  /** 0–100. */
  score: number
  /** Oldest to newest. The table draws this as a sparkline. */
  activity: readonly number[]
  activityLabel: string
  industry?: string
  region?: string
  email?: string
  website?: string
  phone?: string
  notes?: string
  /** Oldest to newest. The detail panel draws this as a trend. */
  trend?: readonly { key: string; label: string; value: number }[]
  /** 0–100 health for the meter. Falls back to score. */
  health?: number
}

export type CrmNotice = {
  id: string
  title: string
  description?: string
  time: string
  dateTime?: string
  read?: boolean
  companyId?: string
}

export type CrmSortKey = "name" | "status" | "owner" | "pipeline" | "score" | "activity"

export type CrmSort = {
  key: CrmSortKey
  direction: "asc" | "desc"
}

export type CrmFacetSelection = Record<string, readonly string[]>

export type CrmCompanyQuery = {
  search?: string
  /** Status id, or the all-segment id. */
  segment?: string
  allSegment?: string
  facets?: CrmFacetSelection
}

export type CrmCsvLabels = {
  name: string
  status: string
  owner: string
  pipeline: string
  score: string
  activity: string
}

export type CrmCompanyDraft = {
  name: string
  status: string
  ownerId: string
  email: string
  website: string
  industry: string
  region: string
  pipelineValue: string
  notes: string
  logo?: { type: string; size: number } | null
}

export type CrmDraftIssue =
  | "name-required"
  | "status-required"
  | "owner-required"
  | "email-invalid"
  | "website-invalid"
  | "pipeline-invalid"
  | "logo-type"
  | "logo-size"

export const CRM_LOGO_TYPES = ["image/png", "image/jpeg", "image/webp", "image/gif"] as const
export const CRM_LOGO_MAX_BYTES = 2_000_000

export const EMPTY_COMPANY_DRAFT: CrmCompanyDraft = {
  name: "",
  status: "",
  ownerId: "",
  email: "",
  website: "",
  industry: "",
  region: "",
  pipelineValue: "",
  notes: "",
  logo: null,
}

export function crmInitials(name: string) {
  const parts = name.split(/\s+/).filter(Boolean).slice(0, 2)
  const letters = parts.map((part) => [...part][0] ?? "").join("")
  return letters.toLocaleUpperCase() || "?"
}

export function companyFacetValue(company: CrmCompany, facetId: string) {
  if (facetId === "owner") return company.ownerId ?? company.owner
  if (facetId === "industry") return company.industry ?? ""
  if (facetId === "region") return company.region ?? ""
  if (facetId === "status") return company.status
  return ""
}

export function companySearchText(company: CrmCompany) {
  return [company.name, company.owner, company.statusLabel, company.industry, company.region, company.email]
    .filter(Boolean)
    .join(" ")
    .toLocaleLowerCase()
}

export function facetSelectionCount(selection: CrmFacetSelection) {
  return Object.values(selection).reduce((sum, values) => sum + values.length, 0)
}

export function toggleFacetValue(selection: CrmFacetSelection, facetId: string, value: string): CrmFacetSelection {
  const current = selection[facetId] ?? []
  const next = current.includes(value) ? current.filter((item) => item !== value) : [...current, value]
  return { ...selection, [facetId]: next }
}

export function filterCompanies(rows: readonly CrmCompany[], query: CrmCompanyQuery = {}) {
  const search = query.search?.trim().toLocaleLowerCase() ?? ""
  const allSegment = query.allSegment ?? "all"
  const segment = query.segment && query.segment !== allSegment ? query.segment : ""
  const facets = Object.entries(query.facets ?? {}).filter(([, values]) => values.length > 0)

  return rows.filter((company) => {
    if (segment && company.status !== segment) return false
    if (search && !companySearchText(company).includes(search)) return false
    return facets.every(([facetId, values]) => values.includes(companyFacetValue(company, facetId)))
  })
}

function sortValue(company: CrmCompany, key: CrmSortKey) {
  switch (key) {
    case "name":
      return company.name
    case "status":
      return company.statusLabel
    case "owner":
      return company.owner
    case "pipeline":
      return company.pipelineValue
    case "score":
      return company.score
    case "activity":
      return company.activity.at(-1) ?? 0
    default: {
      const unreachable: never = key
      return unreachable
    }
  }
}

export function sortCompanies(rows: readonly CrmCompany[], sort: CrmSort) {
  const direction = sort.direction === "asc" ? 1 : -1
  return [...rows].sort((a, b) => {
    const left = sortValue(a, sort.key)
    const right = sortValue(b, sort.key)
    const compared =
      typeof left === "number" && typeof right === "number"
        ? left - right
        : String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: "base" })
    if (compared !== 0) return compared * direction
    return a.id.localeCompare(b.id)
  })
}

export function paginate<T>(rows: readonly T[], page: number, pageSize: number) {
  const size = Math.max(1, Math.floor(pageSize) || 1)
  const total = rows.length
  const pages = Math.max(1, Math.ceil(total / size))
  const index = Math.min(Math.max(0, Math.floor(page) || 0), pages - 1)
  const start = index * size
  return {
    page: index,
    pages,
    start,
    end: Math.min(total, start + size),
    total,
    rows: rows.slice(start, start + size),
  }
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
const WEBSITE = /^https?:\/\/\S+$/i

export function companyDraftIssues(draft: CrmCompanyDraft): CrmDraftIssue[] {
  const issues: CrmDraftIssue[] = []
  if (!draft.name.trim()) issues.push("name-required")
  if (!draft.status) issues.push("status-required")
  if (!draft.ownerId) issues.push("owner-required")
  if (draft.email.trim() && !EMAIL.test(draft.email.trim())) issues.push("email-invalid")
  if (draft.website.trim() && !WEBSITE.test(draft.website.trim())) issues.push("website-invalid")
  const pipeline = Number(draft.pipelineValue)
  if (draft.pipelineValue.trim() === "" || !Number.isFinite(pipeline) || pipeline < 0) issues.push("pipeline-invalid")
  if (draft.logo && draft.logo.size > 0) {
    if (!CRM_LOGO_TYPES.includes(draft.logo.type as (typeof CRM_LOGO_TYPES)[number])) issues.push("logo-type")
    if (draft.logo.size > CRM_LOGO_MAX_BYTES) issues.push("logo-size")
  }
  return issues
}

export function companyFromDraft(
  draft: CrmCompanyDraft & { logoUrl?: string },
  context: {
    id: string
    ownerName: string
    statusLabel: string
    statusTone?: CrmStatusTone
    activityLabel: string
  },
): CrmCompany {
  const pipelineValue = Number(draft.pipelineValue)
  return {
    id: context.id,
    name: draft.name.trim(),
    logoUrl: draft.logoUrl,
    status: draft.status,
    statusLabel: context.statusLabel,
    statusTone: context.statusTone,
    owner: context.ownerName,
    ownerId: draft.ownerId,
    pipelineValue: Number.isFinite(pipelineValue) ? pipelineValue : 0,
    score: 50,
    health: 50,
    activity: [2, 2, 3, 3],
    activityLabel: context.activityLabel,
    industry: draft.industry.trim() || undefined,
    region: draft.region.trim() || undefined,
    email: draft.email.trim() || undefined,
    website: draft.website.trim() || undefined,
    notes: draft.notes.trim() || undefined,
    trend: [{ key: "now", label: context.activityLabel, value: 1 }],
  }
}

export type CsvColumn = {
  key: string
  header: string
}

export function escapeCsvCell(value: unknown): string {
  if (value == null) return ""
  let text = String(value)
  // Spreadsheets treat a leading = + - @ tab or line break as a formula.
  if (typeof value === "string" && /^[=+\-@\t\r\n]/.test(text)) text = `'${text}`
  if (/[",\n\r']/.test(text)) return `"${text.replace(/"/g, '""')}"`
  return text
}

export function toCsv(
  rows: readonly Record<string, unknown>[],
  columns: readonly CsvColumn[],
): string {
  const head = columns.map((column) => escapeCsvCell(column.header)).join(",")
  const body = rows
    .map((row) => columns.map((column) => escapeCsvCell(row[column.key])).join(","))
    .join("\n")
  return body ? `${head}\n${body}` : head
}

export function downloadCsv(filename: string, csv: string) {
  if (typeof document === "undefined") return
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = filename.endsWith(".csv") ? filename : `${filename}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

"use client"

/** Adapted from Arc UI (MIT). */

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from "react"
import { AnimatePresence, animate, motion, useInView, useMotionValue, useMotionValueEvent, useReducedMotion, useTransform, type Variants } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export interface SparklineProps {
  data: number[]
  label: string
  value?: string
  change?: string
  tone?: "accent" | "success" | "warning" | "danger"
  width?: number
  height?: number
  /** One label per point, such as a date. It replaces the change while that point is scrubbed. */
  labels?: string[]
  /** Formats a scrubbed point for the headline. Defaults to a grouped number. */
  formatValue?: (value: number, index: number) => string
  /** A quiet neutral fill under the line. */
  area?: boolean
  /** Pointer and keyboard scrubbing through the points. */
  interactive?: boolean
  className?: string
  classNames?: SparklineClassNames
}

export type SparklineClassNames = {
  root?: string
  caption?: string
  label?: string
  value?: string
  change?: string
  plot?: string
}

const toneClass = {
  accent: "text-primary",
  success: "text-[color:var(--chart-2)]",
  warning: "text-[color:var(--chart-4)]",
  danger: "text-destructive",
} as const

const rise: Variants = {
  hidden: (direction: number) => ({ opacity: 0, y: `${0.3 * direction}em`, filter: `blur(${motionPresets.blur.soft}px)` }),
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.standard, ease: [...motionPresets.ease.enter] } },
  gone: (direction: number) => ({ opacity: 0, y: `${-0.3 * direction}em`, filter: `blur(${motionPresets.blur.subtle}px)`, transition: { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } }),
}
const fade: Variants = {
  hidden: { opacity: 0, y: 0, filter: "blur(0px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
  gone: { opacity: 0, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
}
const amountIn = (text: string) => Number(text.replace(/,/g, "").replace(/−/g, "-").match(/-?\d+(?:\.\d+)?/)?.[0] ?? NaN)
const grouped = new Intl.NumberFormat("en-US")
const draw = { duration: motionPresets.duration.considered * 1.75, ease: [...motionPresets.ease.inOut] } as const
const quick = { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] } as const

type Chunk = { slot: string; key: string; text: string }

function chunksOf(text: string, whole: boolean): Chunk[] {
  if (!text) return []
  if (whole) return [{ slot: "all", key: text, text }]
  if (!/\p{L}/u.test(text)) return [...text].map((char, index, all) => ({ slot: `n${all.length - index}`, key: char, text: char }))
  const words = text.split(/(?<=\s)/)
  return words.map((word, index) => ({ slot: `w${index}`, key: words.slice(0, index + 1).join(""), text: word }))
}

function Roll({ text, direction, whole = false, morph = false, className }: { text: string; direction?: number; whole?: boolean; morph?: boolean; className?: string }) {
  const reduceMotion = !!useReducedMotion()
  const sizer = useRef<HTMLSpanElement>(null)
  const width = useMotionValue<number | "auto">("auto")
  const [shown, setShown] = useState({ text, direction: 1 })
  if (shown.text !== text) setShown({ text, direction: direction ?? (amountIn(text) < amountIn(shown.text) ? -1 : 1) })
  useEffect(() => {
    const node = sizer.current
    if (!node || typeof ResizeObserver === "undefined") return
    let measured: string | null = null
    const observer = new ResizeObserver(([entry]) => {
      const next = entry.borderBoxSize?.[0]?.inlineSize ?? node.offsetWidth
      if (measured !== null && measured !== node.textContent && !reduceMotion) animate(width, next, motionPresets.spring.morph)
      else width.jump(next)
      measured = node.textContent
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [morph, reduceMotion, width])
  const numeric = !whole && !/\p{L}/u.test(text)
  const variants = reduceMotion ? fade : rise
  const anchor = numeric ? "right" : "left"
  return (
    <motion.span className={cn("relative inline-flex max-w-full overflow-x-clip align-top whitespace-pre", numeric && "justify-end", className)} style={morph ? { width } : undefined}>
      {morph ? <span ref={sizer} className="pointer-events-none absolute top-0 left-0 whitespace-pre invisible" aria-hidden="true">{text}</span> : null}
      <span className="relative inline-block whitespace-pre">
        <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
          {chunksOf(text, whole).map((chunk) => (
            <motion.span key={chunk.slot} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">
              <AnimatePresence mode="popLayout" initial={false} custom={shown.direction} anchorX={anchor}>
                <motion.span key={chunk.key} className={cn("relative inline-block whitespace-pre", whole && "max-w-full overflow-hidden text-ellipsis align-top")} custom={shown.direction} variants={variants} initial="hidden" animate="shown" exit="gone">{chunk.text}</motion.span>
              </AnimatePresence>
            </motion.span>
          ))}
        </AnimatePresence>
      </span>
    </motion.span>
  )
}

type Point = [number, number]
const inset = 5
const cap = 1.25
const grid = Array.from({ length: 161 }, (_, index) => index / 160)

function curveFor(data: number[]): Point[] {
  const min = Math.min(...data)
  const span = Math.max(...data) - min
  const ys = data.map((value) => (span ? (value - min) / span : 0.5))
  const last = ys.length - 1
  const step = 1 / last
  const slopes = ys.slice(1).map((y, index) => (y - ys[index]) / step)
  const tangents = ys.map((_, index) => (index === 0 || index === last ? slopes[0] : (Math.sign(slopes[index - 1]) + Math.sign(slopes[index])) * Math.min(Math.abs(slopes[index - 1]), Math.abs(slopes[index]), Math.abs(slopes[index - 1] + slopes[index]) / 4) || 0))
  if (last > 1) {
    tangents[0] = (3 * slopes[0] - tangents[1]) / 2
    tangents[last] = (3 * slopes[last - 1] - tangents[last - 1]) / 2
  }
  const samples = Math.max(1, Math.min(16, Math.round(128 / last)))
  const points: Point[] = []
  for (let index = 0; index < last; index++) {
    for (let sample = 0; sample < samples; sample++) {
      const t = sample / samples
      const t2 = t * t
      const t3 = t2 * t
      const y = (2 * t3 - 3 * t2 + 1) * ys[index] + (t3 - 2 * t2 + t) * step * tangents[index] + (3 * t2 - 2 * t3) * ys[index + 1] + (t3 - t2) * step * tangents[index + 1]
      points.push([(index + t) * step, Math.min(1, Math.max(0, y))])
    }
  }
  points.push([1, ys[last]])
  return points
}

function heightAt(shape: Point[], x: number) {
  let low = 0
  let high = shape.length - 1
  if (x <= shape[low][0]) return shape[low][1]
  if (x >= shape[high][0]) return shape[high][1]
  while (high - low > 1) {
    const middle = (low + high) >> 1
    if (shape[middle][0] < x) low = middle
    else high = middle
  }
  const [x0, y0] = shape[low]
  const [x1, y1] = shape[high]
  return x1 === x0 ? y1 : y0 + ((y1 - y0) * (x - x0)) / (x1 - x0)
}

function geometryOf(shape: Point[], w: number, h: number, at: number) {
  const toY = (y: number) => inset + (1 - y) * (h - inset * 2)
  const points = shape.map(([x, y]): Point => [x * w, toY(y)])
  const pairs = points.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`)
  const cx = at * w
  const cy = toY(heightAt(shape, at))
  return { points, line: pairs.join(" "), trail: `M${pairs.join("L")}`, fill: `M${pairs.join("L")}L${w},${h}L0,${h}Z`, dot: `${cx},${cy} ${cx},${cy}`, cx }
}

function tipAt(points: Point[], progress: number) {
  const steps = points.slice(1).map(([x, y], index) => Math.hypot(x - points[index][0], y - points[index][1]))
  let left = progress * steps.reduce((sum, step) => sum + step, 0)
  for (let index = 0; index < steps.length; index++) {
    if (left <= steps[index]) return points[index][0] + (points[index + 1][0] - points[index][0]) * (steps[index] ? left / steps[index] : 1)
    left -= steps[index]
  }
  return points[points.length - 1][0]
}

export function Sparkline({ data, label, value, change, tone = "accent", width = 160, height = 52, labels, formatValue, area = true, interactive = true, className, classNames }: SparklineProps) {
  const safeData = data.length > 1 ? data : [data[0] ?? 0, data[0] ?? 0]
  const last = safeData.length - 1
  const key = safeData.join(",")
  const target = useMemo(() => curveFor(key.split(",").map(Number)), [key])
  const description = `${label}: ${value ?? safeData[last]}. ${change ?? ""}`.trim()
  const uid = `sparkline${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const ref = useRef<HTMLElement>(null)
  const plot = useRef<HTMLDivElement>(null)
  const inView = useInView(ref, { once: true, amount: 0.5 })
  const reduceMotion = !!useReducedMotion()
  const [box, setBox] = useState({ w: width, h: height })
  const [active, setActive] = useState<number | null>(null)
  const [landed, setLanded] = useState(false)
  const index = active === null ? null : Math.min(active, last)
  const [moved, setMoved] = useState({ index, direction: 1 })
  if (moved.index !== index) setMoved({ index, direction: index === null || moved.index === null ? 1 : Math.sign(index - moved.index) || 1 })

  const [first] = useState(() => geometryOf(target, width, height, 1))
  const shape = useRef(target)
  const size = useRef(box)
  const drawn = useMotionValue(0)
  const cursor = useMotionValue(1)
  const line = useMotionValue(first.line)
  const trail = useMotionValue(first.trail)
  const fill = useMotionValue(first.fill)
  const dot = useMotionValue(first.dot)
  const cursorX = useMotionValue(first.cx)
  const lit = useMotionValue(first.cx + cap + 16)
  const dim = useMotionValue(first.cx + cap)
  const reveal = useMotionValue(0)
  const lineOpacity = useTransform(drawn, (progress) => (progress > 0.001 ? 1 : 0))
  const stroke = toneClass[tone]

  const paint = useCallback(() => {
    const { w, h } = size.current
    const progress = drawn.get()
    const next = geometryOf(shape.current, w, h, cursor.get())
    line.set(next.line)
    trail.set(next.trail)
    fill.set(next.fill)
    dot.set(next.dot)
    cursorX.set(next.cx)
    lit.set(next.cx + cap + 16)
    dim.set(next.cx + cap)
    reveal.set(progress >= 1 ? w + 32 : tipAt(next.points, progress) + 16)
  }, [cursor, cursorX, dim, dot, drawn, fill, line, lit, reveal, trail])
  useMotionValueEvent(cursor, "change", paint)
  useMotionValueEvent(drawn, "change", paint)

  useLayoutEffect(() => {
    const node = plot.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      const w = node.clientWidth
      if (w) setBox((current) => (Math.abs(current.w - w) < 0.5 ? current : { w, h: (w * height) / width }))
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [height, width])
  useLayoutEffect(() => {
    size.current = box
    paint()
  }, [box, paint])

  useEffect(() => {
    if (reduceMotion) {
      drawn.jump(1)
      const frame = requestAnimationFrame(() => setLanded(true))
      return () => cancelAnimationFrame(frame)
    }
    if (!inView) return
    const controls = animate(drawn, 1, { ...draw, onComplete: () => setLanded(true) })
    return () => controls.stop()
  }, [drawn, inView, reduceMotion])

  useEffect(() => {
    const from = shape.current
    if (from === target) return
    if (reduceMotion) {
      shape.current = target
      paint()
      return
    }
    const xs = [...new Set([...grid, ...target.map(([x]) => x)])].sort((a, b) => a - b)
    const start = xs.map((x) => heightAt(from, x))
    const goal = xs.map((x) => heightAt(target, x))
    const controls = animate(0, 1, {
      ...motionPresets.spring.smooth,
      onUpdate: (progress) => {
        shape.current = xs.map((x, at): Point => [x, start[at] + (goal[at] - start[at]) * progress])
        paint()
      },
      onComplete: () => {
        shape.current = target
        paint()
      },
    })
    return () => controls.stop()
  }, [paint, reduceMotion, target])

  useEffect(() => {
    const to = index === null ? 1 : index / last
    if (reduceMotion) {
      cursor.jump(to)
      return
    }
    const controls = animate(cursor, to, motionPresets.spring.snappy)
    return () => controls.stop()
  }, [cursor, index, last, reduceMotion])

  const scrubbing = index !== null
  const format = (at: number) => (formatValue ? formatValue(safeData[at], at) : grouped.format(safeData[at]))
  const point = format(index ?? last)
  const when = labels?.[index ?? last]
  const headline = value === undefined ? undefined : scrubbing ? point : value
  const aside = index === null ? change ?? "" : value === undefined ? [point, when].filter(Boolean).join(" · ") : when ?? `${index + 1} of ${last + 1}`
  const pointAt = (clientX: number) => {
    const rect = plot.current?.getBoundingClientRect()
    return rect?.width ? Math.max(0, Math.min(last, Math.round(((clientX - rect.left) / rect.width) * last))) : last
  }
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape" && scrubbing) {
      event.preventDefault()
      setActive(null)
      return
    }
    const from = index ?? last
    const page = Math.max(1, Math.round((last + 1) / 6))
    const next = ({ ArrowLeft: from - 1, ArrowDown: from - 1, ArrowRight: from + 1, ArrowUp: from + 1, PageDown: from - page, PageUp: from + page, Home: 0, End: last } as Record<string, number>)[event.key]
    if (next === undefined) return
    event.preventDefault()
    setActive(Math.max(0, Math.min(last, next)))
  }
  const scrub = interactive
    ? {
        role: "slider" as const,
        tabIndex: 0,
        "aria-label": `${label}, explore values`,
        "aria-valuemin": 1,
        "aria-valuemax": last + 1,
        "aria-valuenow": (index ?? last) + 1,
        "aria-valuetext": `${when ?? (index === null ? "Latest" : `Point ${index + 1} of ${last + 1}`)}: ${point}`,
        onPointerDown: (event: PointerEvent<HTMLDivElement>) => setActive(pointAt(event.clientX)),
        onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType === "mouse" || event.buttons) setActive(pointAt(event.clientX))
        },
        onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
          if (event.pointerType !== "mouse") setActive(null)
        },
        onPointerLeave: () => setActive(null),
        onPointerCancel: () => setActive(null),
        onBlur: () => setActive(null),
        onKeyDown,
      }
    : {}

  return (
    <figure ref={ref} data-slot="sparkline" aria-label={description} className={cn("grid min-w-0 gap-3 text-foreground", className, classNames?.root)}>
      <figcaption data-slot="sparkline-caption" className={cn("flex min-w-0 items-baseline gap-2 text-sm text-muted-foreground", classNames?.caption)}>
        <span data-slot="sparkline-label" className={cn("min-w-0 overflow-hidden whitespace-nowrap", classNames?.label)}>
          <Roll text={label} whole />
        </span>
        {headline !== undefined ? (
          <strong data-slot="sparkline-value" className={cn("ml-auto text-lg font-medium text-foreground tabular-nums", classNames?.value)}>
            <Roll text={headline} morph />
          </strong>
        ) : null}
        <small data-slot="sparkline-change" className={cn("shrink-0 text-xs font-medium tabular-nums transition-colors", stroke, scrubbing && "text-muted-foreground", classNames?.change)}>
          <Roll text={aside} direction={scrubbing ? moved.direction : undefined} morph />
        </small>
      </figcaption>
      <div
        ref={plot}
        data-slot="sparkline-plot"
        data-interactive={interactive || undefined}
        className={cn("relative min-w-0 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-offset-8", interactive && "cursor-default touch-pan-y select-none", classNames?.plot)}
        {...scrub}
      >
        <svg data-slot="sparkline-chart" className="block h-auto w-full overflow-visible" viewBox={`0 0 ${box.w} ${box.h}`} aria-hidden="true" focusable="false">
          <defs>
            <clipPath id={`${uid}-lit`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={lit} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-dim`} clipPathUnits="userSpaceOnUse"><motion.rect x={dim} y={-16} width={box.w + 32} height={box.h + 32} /></clipPath>
            <clipPath id={`${uid}-fill`} clipPathUnits="userSpaceOnUse"><motion.rect x={-16} y={-16} width={reveal} height={box.h + 32} /></clipPath>
          </defs>
          {area ? <motion.path className={cn("fill-current stroke-none opacity-10", stroke)} d={fill} clipPath={`url(#${uid}-fill)`} /> : null}
          <line className="stroke-border" strokeWidth={1} x1="0" y1={box.h - 0.5} x2={box.w} y2={box.h - 0.5} />
          <motion.path className="fill-none stroke-border stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]" d={trail} clipPath={`url(#${uid}-dim)`} initial={false} animate={{ opacity: scrubbing && landed ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current stroke-[2.5] [stroke-linecap:round] [stroke-linejoin:round]", stroke)} points={line} clipPath={`url(#${uid}-lit)`} style={{ pathLength: drawn, opacity: lineOpacity }} />
          <motion.line className="stroke-border" strokeWidth={1} x1={cursorX} x2={cursorX} y1={0} y2={box.h} initial={false} animate={{ opacity: scrubbing ? 1 : 0 }} transition={reduceMotion ? { duration: 0 } : quick} />
          <motion.polyline className={cn("fill-none stroke-current", stroke)} points={dot} initial={false} animate={{ opacity: landed ? 1 : 0, strokeWidth: landed ? (scrubbing ? 10 : 7) : 0 }} transition={reduceMotion ? { duration: 0 } : { opacity: quick, strokeWidth: motionPresets.spring.snappy }} strokeLinecap="round" />
        </svg>
      </div>
    </figure>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
